def detect_bias(model_predictions, protected_attributes):
    """
    Basic function to detect potential bias in AI model predictions
    across different protected attributes.
    """
    bias_results = {}

    for attr in protected_attributes:
        groups = set(attr)
        group_performance = {}

        for group in groups:
            group_indices = [i for i, a in enumerate(attr) if a == group]
            group_preds = [model_predictions[i] for i in group_indices]
            group_performance[group] = sum(group_preds) / len(group_preds)

        bias_results[attr] = group_performance

    return bias_results
